def move_type_up(conn, type_id):
    """Перемещает тип оборудования на одну позицию вверх"""
    cursor = conn.cursor()

    # Получаем текущий порядок типа
    cursor.execute("SELECT sort_order FROM equipment_types WHERE id = ?", (type_id,))
    current_order = cursor.fetchone()[0]

    # Получаем тип с предыдущим порядком
    cursor.execute("SELECT id, sort_order FROM equipment_types WHERE sort_order < ? ORDER BY sort_order DESC LIMIT 1",
                   (current_order,))
    previous_type = cursor.fetchone()

    if previous_type:
        previous_id, previous_order = previous_type

        # Временно устанавливаем уникальные значения чтобы избежать конфликта UNIQUE
        cursor.execute("UPDATE equipment_types SET sort_order = -1 WHERE id = ?", (type_id,))
        cursor.execute("UPDATE equipment_types SET sort_order = ? WHERE id = ?", (current_order, previous_id))
        cursor.execute("UPDATE equipment_types SET sort_order = ? WHERE id = ?", (previous_order, type_id))

        conn.commit()


def move_type_down(conn, type_id):
    """Перемещает тип оборудования на одну позицию вниз"""
    cursor = conn.cursor()

    # Получаем текущий порядок типа
    cursor.execute("SELECT sort_order FROM equipment_types WHERE id = ?", (type_id,))
    current_order = cursor.fetchone()[0]

    # Получаем тип со следующим порядком
    cursor.execute("SELECT id, sort_order FROM equipment_types WHERE sort_order > ? ORDER BY sort_order ASC LIMIT 1",
                   (current_order,))
    next_type = cursor.fetchone()

    if next_type:
        next_id, next_order = next_type

        # Временно устанавливаем уникальные значения чтобы избежать конфликта UNIQUE
        cursor.execute("UPDATE equipment_types SET sort_order = -1 WHERE id = ?", (type_id,))
        cursor.execute("UPDATE equipment_types SET sort_order = ? WHERE id = ?", (current_order, next_id))
        cursor.execute("UPDATE equipment_types SET sort_order = ? WHERE id = ?", (next_order, type_id))

        conn.commit()


def recalculate_type_order(conn):
    """Пересчитывает порядок сортировки после удаления типа"""
    cursor = conn.cursor()
    cursor.execute("SELECT id FROM equipment_types ORDER BY sort_order")
    types = cursor.fetchall()

    for i, (type_id,) in enumerate(types):
        cursor.execute("UPDATE equipment_types SET sort_order = ? WHERE id = ?", (i + 1, type_id))

    conn.commit()


# Страница оборудования
def show_equipment_page(conn):
    st.header("🏭 Оборудование")

    col1, col2 = st.columns([1, 2])

    with col1:
        st.subheader("Добавить оборудование")
        with st.form("add_equipment", clear_on_submit=True):
            name = st.text_input("Наименование оборудования*")
            sort_order = st.number_input(
                "Порядковый номер*",
                min_value=1,
                value=get_next_sort_order(conn, 'equipment')
            )
            show_on_chart = st.checkbox("Показывать на диаграмме", value=True)

            types_df = pd.read_sql("SELECT * FROM equipment_types ORDER BY sort_order", conn)
            if not types_df.empty:
                type_options = {row['id']: row['name'] for _, row in types_df.iterrows()}
                selected_type = st.selectbox("Тип оборудования*", options=list(type_options.keys()),
                                             format_func=lambda x: type_options[x])
            else:
                st.warning("Сначала добавьте типы оборудования")
                selected_type = None

            if st.form_submit_button("Добавить оборудование") and selected_type:
                if not name:
                    st.error("Введите наименование оборудования")
                elif not is_sort_order_unique(conn, 'equipment', sort_order):
                    st.error("Порядковый номер уже занят")
                else:
                    try:
                        cursor = conn.cursor()
                        cursor.execute(
                            "INSERT INTO equipment (name, sort_order, show_on_chart, type_id) VALUES (?, ?, ?, ?)",
                            (name, sort_order, show_on_chart, selected_type)
                        )
                        conn.commit()
                        st.success("✅ Оборудование добавлено!")
                        st.rerun()
                    except sqlite3.IntegrityError:
                        st.error("❌ Оборудование с таким именем уже существует")

    with col2:
        st.subheader("Список оборудования")

        # ФИЛЬТР ПО ТИПУ ОБОРУДОВАНИЯ
        col_filter1, col_filter2 = st.columns([2, 1])
        with col_filter1:
            # Загружаем типы оборудования для фильтра
            types_df = pd.read_sql("SELECT * FROM equipment_types ORDER BY sort_order", conn)
            type_options = ["Все"] + [row['name'] for _, row in types_df.iterrows()]
            selected_type_filter = st.selectbox(
                "Фильтр по типу оборудования",
                options=type_options,
                key="equipment_type_filter"
            )

        with col_filter2:
            # Фильтр по отображению на диаграмме
            show_filter = st.selectbox(
                "Показывать",
                options=["Все", "На диаграмме", "Скрытые"],
                key="equipment_show_filter"
            )

        equipment_df = pd.read_sql('''
            SELECT e.*, et.name as type_name, et.color as type_color 
            FROM equipment e 
            JOIN equipment_types et ON e.type_id = et.id 
            ORDER BY et.sort_order, e.sort_order
        ''', conn)

        if not equipment_df.empty:
            # Применяем фильтры
            filtered_equipment = equipment_df.copy()

            # Фильтр по типу оборудования
            if selected_type_filter != "Все":
                filtered_equipment = filtered_equipment[filtered_equipment['type_name'] == selected_type_filter]

            # Фильтр по отображению на диаграмме
            if show_filter == "На диаграмме":
                filtered_equipment = filtered_equipment[filtered_equipment['show_on_chart'] == 1]
            elif show_filter == "Скрытые":
                filtered_equipment = filtered_equipment[filtered_equipment['show_on_chart'] == 0]

            # Показываем статистику фильтрации
            st.info(f"📊 Найдено оборудования: {len(filtered_equipment)}")

            for _, row in filtered_equipment.iterrows():
                # Добавляем значок видимости на диаграмме
                visibility_icon = "👁️" if row['show_on_chart'] else "👁️‍🗨️"

                with st.expander(f"{visibility_icon} {row['name']} ({row['type_name']})"):
                    col21, col22, col23, col24 = st.columns(4)

                    with col21:
                        new_name = st.text_input("Наименование", value=row['name'], key=f"eq_name_{row['id']}")
                    with col22:
                        new_order = st.number_input("Порядок", value=row['sort_order'], key=f"eq_order_{row['id']}")
                    with col23:
                        new_show = st.checkbox("На диаграмме", value=bool(row['show_on_chart']),
                                               key=f"eq_show_{row['id']}")
                    with col24:
                        types_df = pd.read_sql("SELECT * FROM equipment_types ORDER BY sort_order", conn)
                        type_options = {row['id']: row['name'] for _, row in types_df.iterrows()}
                        new_type = st.selectbox("Тип", options=list(type_options.keys()),
                                                index=list(type_options.keys()).index(row['type_id']),
                                                format_func=lambda x: type_options[x], key=f"eq_type_{row['id']}")

                    col25, col26 = st.columns(2)
                    with col25:
                        if st.button("💾 Сохранить", key=f"eq_save_{row['id']}"):
                            if not is_sort_order_unique(conn, 'equipment', new_order, row['id']):
                                st.error("Порядковый номер уже занят")
                            else:
                                cursor = conn.cursor()
                                cursor.execute(
                                    "UPDATE equipment SET name=?, sort_order=?, show_on_chart=?, type_id=? WHERE id=?",
                                    (new_name, new_order, new_show, new_type, row['id'])
                                )
                                conn.commit()
                                st.success("Оборудование обновлено!")
                                st.rerun()

                    with col26:
                        if st.button("🗑️ Удалить", key=f"eq_delete_{row['id']}"):
                            cursor = conn.cursor()
                            cursor.execute("SELECT COUNT(*) FROM jobs WHERE equipment_id=?", (row['id'],))
                            jobs_count = cursor.fetchone()[0]

                            if jobs_count > 0:
                                st.error(f"Нельзя удалить: связано {jobs_count} работ")
                            else:
                                cursor.execute("DELETE FROM equipment WHERE id=?", (row['id'],))
                                conn.commit()
                                st.success("Оборудование удалено!")
                                st.rerun()
        else:
            st.info("📝 Нет оборудования. Добавьте первое оборудование.")


